static uint8_t Hacl_Impl_Select_eq_mask_bytes(uint8_t *a, uint8_t *b, size_t len) {
  uint8_t acc = Hacl_Secret_UInt8_ones;
  size_t i = 0;
  while (i < len) {
    size_t vi = i;
    uint8_t vacc = acc;
    uint8_t x = a[vi];
    uint8_t y = b[vi];
    uint8_t m = Hacl_Secret_UInt8_eq_mask(x, y);
    acc = Hacl_Secret_UInt8_logand(vacc, m);
    i = (vi + 1);
  }
  return acc;
}

