    uint64_t old = c[pos];
    unsigned __int128 t = Hacl_Secret_UInt128_add_mod(Hacl_Secret_UInt128_add_mod(Hacl_Secret_Cast_u64_to_u128(old), Hacl_Secret_Cast_u64_to_u128(cr)), Hacl_Secret_Cast_u64_to_u128(vov));
